### 4. Authentication & authorization checks

If `app.js` handles auth:

- **Validate and parse tokens securely:**
  - Use `jsonwebtoken` with:
    - Strong secret (env var, at least 256 bits for HS256).
    - Explicit `alg` verification.
  - Example:

    ```js
    const jwt = require('jsonwebtoken');
    const JWT_SECRET = process.env.JWT_SECRET;

    function authMiddleware(req, res, next) {
      const authHeader = req.headers.authorization || '';
      const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7) : null;
      if (!token) return res.status(401).json({ error: 'Missing token' });

      try {
        const payload = jwt.verify(token, JWT_SECRET, { algorithms: ['HS256'] });
        req.user = payload;
        next();
      } catch (err) {
        return res.status(401).json({ error: 'Invalid token' });
      }
    }
    ```

- **Enforce authorization at route level:**

  ```js
  function requireRole(role) {
    return (req, res, next) => {
      if (!req.user || req.user.role !== role) {
        return res.status(403).json({ error: 'Forbidden' });
      }
      next();
    };
  }

  app.delete('/admin/users/:id', authMiddleware, requireRole('admin'), asyncHandler(...));
  ```

---

### 5. Secure configuration and secrets

- **Never hardcode secrets** in `app.js`:
  - Use environment variables for DB passwords, JWT secrets, API keys.
- Validate critical env vars on startup:
  ```js
